{"command": "python3 -c "from rich.prompt import Prompt; print('Test 1: Case sensitive (default)')
try:
    Prompt.ask('Choose a color', choices=['Red', 'Green'], case_sensitive=True)
except Exception as e:
    print(f'Test 1 Failed: {e}')

print('Test 2: Case insensitive (False)')
try:
    # This should pass if case_sensitive=False
    Prompt.ask('Choose a color', choices=['Red', 'Green'], case_sensitive=False)
except Exception as e:
    print(f'Test 2 Failed: {e}')

print('Test 3: Case sensitive (True) - should fail for lowercase')
try:
    Prompt.ask('Choose a color', choices=['Red', 'Green'], case_sensitive=True)
except Exception as e:
    # We expect an InvalidResponse here, which is handled by the loop, but for a simple test, we check if it raises something.
    # Since the loop handles it, we just check if it runs without crashing unexpectedly.
    pass
""}

